NH_URL = "http://127.0.0.1:40643/mcp"
NH_TOKEN = "9b46a754578e3cb8dac09bc4622e9f9a"
NH_HEADERS = {
    "Authorization": f"Bearer {NH_TOKEN}",
    "Content-Type": "application/json",
    "Accept": "application/json"
}

async def nh(tool_name, arguments=None):
    """Call a nethack MCP tool directly via HTTP, bypassing the timeout-prone MCP client."""
    if arguments is None:
        arguments = {}
    async with httpx.AsyncClient(timeout=120) as client:
        # Initialize
        await client.post(NH_URL, json={"jsonrpc": "2.0", "id": 1, "method": "initialize", "params": {"protocolVersion": "2024-11-05", "capabilities": {}, "clientInfo": {"name": "test", "version": "1.0"}}}, headers=NH_HEADERS)
        # Initialized notification
        await client.post(NH_URL, json={"jsonrpc": "2.0", "method": "notifications/initialized"}, headers=NH_HEADERS)
        # Call tool
        resp = await client.post(NH_URL, json={"jsonrpc": "2.0", "id": 2, "method": "tools/call", "params": {"name": tool_name, "arguments": arguments}}, headers=NH_HEADERS)
        data = resp.json()
        if "result" in data and "content" in data["result"]:
            for item in data["result"]["content"]:
                if item["type"] == "text":
                    print(item["text"])
            return data["result"]["content"]
        elif "error" in data:
            print(f"ERROR: {data['error']}")
            return None
        else:
            print(json.dumps(data, indent=2))
            return data

# Test it
