import inspect
for name in ['np_move_to', 'np_go_to', 'np_down', 'np_up', 'np_explore_level', 'np_melee_attack', 'search', 'rollback', 'np_pickup', 'np_look', 'np_eat', 'np_wield', 'np_wear', 'np_read', 'np_apply', 'np_zap', 'np_cast', 'np_pray', 'np_rest', 'np_drop', 'np_set_avoid_monster_flag', 'np_kick', 'np_offer', 'reveal', 'np_press_key', 'np_type_text']:
    tool = getattr(nethack, name, None)
    if tool:
        try:
            sig = inspect.signature(tool)
            print(f"{name}: {sig}")
        except:
            print(f"{name}: (no sig)")
"}

