import re
lines = result_text.split('\n')
game_map_latest = {}
for line in lines:
    # Look for lines starting with "y" followed by a number and colon
    m = re.match(r'^y(\d+):(.*)$', line.strip())
    if m:
        y = int(m.group(1))
        content = m.group(2)
        # The content starts right after the colon - but there might be a leading space
        # Let me check: "y 4:     |...>" -> after "y 4:" there's a space, then content
        # Actually, let me strip the leading space after colon
        if content.startswith(' '):
            content = content[1:]  # Remove one leading space
        for x in range(min(79, len(content))):
            game_map_latest[(x, y)] = content[x]

# Check key positions
