        y = int(line[1:colon_idx].strip())
        content = line[colon_idx+2:]
        for x in range(min(79, len(content))):
            game_map[(x, y)] = content[x]

    # Find stairs down and player
    stairs_down = []
    player_pos = None
    for (x, y), c in game_map.items():
        if c == '>':
